const state = $input.first().json;
const today = new Date().toLocaleDateString('en-MY', { day: 'numeric', month: 'long', year: 'numeric' });

function fmt(n) { return (n || 0).toFixed(2); }

const careTasks = state.kai_care_tasks || [];
const medications = state.kai_medications || [];
const appointments = state.kai_appointments || [];
const householdTasks = state.kai_household_tasks || [];

// Care tasks
const careCompleted = careTasks.filter(t => t.logs && t.logs.length > 0).length;
const careTotal = careTasks.length;
const carePending = careTasks.filter(t => !t.logs || t.logs.length === 0).map(t => t.name);

// Medications
const medTotal = medications.reduce((s, m) => s + (m.schedules ? m.schedules.length : 0), 0);
const medTaken = medications.reduce((s, m) => s + (m.schedules ? m.schedules.filter(sc => sc.taken).length : 0), 0);
const medPct = medTotal > 0 ? Math.round((medTaken / medTotal) * 100) : 0;
const medMissed = medications.flatMap(m => (m.schedules || []).filter(sc => !sc.taken).map(sc => m.name + ' (' + sc.period + ')'));

// Household
const houseCompleted = householdTasks.filter(t => t.logs && t.logs.length > 0).length;
const houseTotal = householdTasks.length;

// Next appointment
const now = new Date();
const future = appointments.filter(a => new Date(a.date + 'T' + a.time) >= now);
future.sort((a, b) => a.date.localeCompare(b.date));
const nextAppt = future[0];

// Overall score
const overallScore = Math.round(
  (careTotal > 0 ? (careCompleted / careTotal) * 40 : 0) +
  (medTotal > 0 ? (medPct / 100) * 40 : 0) +
  (houseTotal > 0 ? (houseCompleted / houseTotal) * 20 : 0)
);

// Status emoji based on score
let statusEmoji = '\u2705';
if (overallScore < 50) statusEmoji = '\u26A0\uFE0F';
else if (overallScore < 75) statusEmoji = '\u{1F7E1}';

const lines = [
  statusEmoji + ' KAI Daily Health Report',
  '\u{1F4C5} ' + today,
  '',
  '\u{1F3AF} Overall Score: ' + overallScore + '/100',
  '',
  '\u{1F3E5} Patient Care: ' + careCompleted + '/' + careTotal + ' tasks completed',
];

if (carePending.length > 0) {
  lines.push('   \u274C Missed: ' + carePending.join(', '));
}

lines.push('');
lines.push('\u{1F48A} Medication: ' + medPct + '% adherence (' + medTaken + '/' + medTotal + ' doses)');

if (medMissed.length > 0) {
  lines.push('   \u274C Missed: ' + medMissed.slice(0, 5).join(', '));
}

lines.push('');
lines.push('\u{1F3E0} Household: ' + houseCompleted + '/' + houseTotal + ' tasks done');
lines.push('');

if (nextAppt) {
  lines.push('\u{1F4C6} Next Appointment: ' + nextAppt.hospital + ' on ' + nextAppt.date + ' at ' + nextAppt.time);
} else {
  lines.push('\u{1F4C6} No upcoming appointments');
}

lines.push('');
lines.push('\u2014 Sent automatically by KAI at 8:00 PM');

return [{ json: { message: lines.join('\n') } }];
